WITH base AS (SELECT *, CAST(temp_c AS INT) temp_c_int FROM device_readings WHERE reading_ts >= TO_DATE('2025-09-01')), cleaned AS (SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, firmware, temp_c_int, temp_c - pressure temp_c_minus_pressure FROM base WHERE reading_ts < '2023-06-17'), with_windows AS (SELECT id, temp_c_minus_pressure, SUM(status_bits) OVER w_running running_sum_status_bits, AVG(status_bits) OVER w_running running_avg_status_bits, MIN(status_bits) OVER w_running running_min_status_bits, ROW_NUMBER() OVER w_running_2 seq_no FROM cleaned WHERE firmware = '2.0.1' WINDOW w_running AS (PARTITION BY device_code ORDER BY temp_c_minus_pressure ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running_2 AS (PARTITION BY device_code ORDER BY temp_c ASC, id ASC)), filtered AS (SELECT *, running_avg_status_bits / NULLIF(running_sum_status_bits, 0) running_avg_status_bits_per_running_sum_status_bits FROM with_windows WHERE temp_c_minus_pressure >= 76), enriched AS (SELECT *, ROW_NUMBER() OVER (ORDER BY running_avg_status_bits DESC, id ASC) row_seq, AVG(running_sum_status_bits) OVER (ORDER BY running_avg_status_bits_per_running_sum_status_bits ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) running_sum_status_bits_avg_2, AVG(seq_no) OVER (ORDER BY temp_c_minus_pressure ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) seq_no_avg_2 FROM filtered) SELECT seq_no, PERCENTILE_APPROX(running_sum_status_bits_avg_2, ARRAY(0.25, 0.5, 0.75)) AS running_sum_status_bits_avg_2_quartiles, ROUND(AVG(running_sum_status_bits), 2) AS avg_running_sum_status_bits, COUNT(*) AS num_rows, COUNT(DISTINCT id) AS distinct_ids FROM enriched GROUP BY seq_no ORDER BY avg_running_sum_status_bits ASC
